import{describe,it,expect,beforeEach}from"vitest";function escapeHTML(e){return e.replace(/[&<>'"]/g,e=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[e]||e))}function addMessage(e,t,s){const c=document.createElement("div");c.className=`message ${t}`;const o="user-message"===t?escapeHTML(e):e;c.innerHTML=`<div class="message-content">${o}</div>`,s.appendChild(c)}describe("Chatbot Message Rendering & Escaping",()=>{let e;beforeEach(()=>{document.body.innerHTML='<div id="chat-messages"></div>',e=document.getElementById("chat-messages")}),it("escapeHTML helper correctly escapes special characters",()=>{const e=escapeHTML('<script>alert("hello & welcome");<\/script>');expect(e).toBe("&lt;script&gt;alert(&quot;hello &amp; welcome&quot;);&lt;/script&gt;")}),it("escapes user messages to prevent XSS injection",()=>{const t="<img src=x onerror=alert(1)>";addMessage(t,"user-message",e);const s=e.querySelector(".user-message .message-content");expect(s).toBeTruthy(),expect(s.innerHTML).toBe("&lt;img src=x onerror=alert(1)&gt;"),expect(s.textContent).toBe(t)}),it("does not escape bot messages to preserve HTML formatting",()=>{const t='Taj Mahal is beautiful. <br><button class="chat-action-btn">Take me there</button>';addMessage(t,"bot-message",e);const s=e.querySelector(".bot-message .message-content");expect(s).toBeTruthy(),expect(s.innerHTML).toBe(t),expect(s.querySelector("button")).toBeTruthy(),expect(s.querySelector("br")).toBeTruthy()})});